async function upsertFinanceRecord(
  workspaceId: string,
  record: {
    id: string;
    voyageId: string;
    vesselName: string;
    recordType: string;
    amount?: number;
    currency?: string;
    status?: string;
    description: string;
    raw: Record<string, unknown>;
  },
  provider: string,
