  | "change-monitor"
  | "audit"
  | "action-plan"
  | "all";

export type ExtractedField = {
  name: string;
  value: string;
  confidence: number;
  excerpt: string;
};

export type DocumentExtractionDraft = {
  documentId: string;
  voyageId: string;
  vesselName: string;
  documentType: string;
  fields: ExtractedField[];
  confidence: number;
  status: ExtractionStatus;
  evidence: WorkflowEvidence[];
};

export type ReconciliationFindingDraft = {
  findingType: string;
  voyageId: string;
